/* Glyph index for byte c: its own slot or the missing-glyph box. */
static inline int geneva12_index(int c)
{
    if (c < GENEVA12_FIRST || c > GENEVA12_LAST)
        return GENEVA12_MISSING;
    return c - GENEVA12_FIRST;
}

/* The pen advance of byte c (the owTable aw). */
static inline int geneva12_advance(int c)
{
    return (int)geneva12_aw[geneva12_index(c)];
}

